package proto

import (
	"os"
	"regexp"
	"testing"
)

// protocGenEsRuntimeVersion is the @bufbuild/protoc-gen-es version the
// companion image must bake. It has to match the @bufbuild/protobuf runtime
// version consumers pin (currently 2.11.0): the generator emits the
// `// @generated by protoc-gen-es v<version>` header and codegen shaped for a
// specific runtime surface, so a companion whose es diverges from a repo's
// pinned runtime makes companion output disagree with committed *_pb.ts forever
// (sync-drift). Bump this only in lockstep with the ecosystem runtime.
const protocGenEsRuntimeVersion = "2.11.0"

var protocGenEsPin = regexp.MustCompile(`@bufbuild/protoc-gen-es@([0-9]+\.[0-9]+\.[0-9]+)`)

func TestDockerfilePinsProtocGenEsToRuntimeVersion(t *testing.T) {
	content, err := os.ReadFile("Dockerfile")
	if err != nil {
		t.Fatalf("read Dockerfile: %v", err)
	}
	match := protocGenEsPin.FindSubmatch(content)
	if match == nil {
		t.Fatal("Dockerfile no longer pins @bufbuild/protoc-gen-es to an explicit version")
	}
	if got := string(match[1]); got != protocGenEsRuntimeVersion {
		t.Fatalf("companion pins protoc-gen-es %s, but the ecosystem runtime is %s; the generator and runtime must move together (see issue #83)", got, protocGenEsRuntimeVersion)
	}
}
